#!/usr/bin/env python3
"""install_toolsmart.py - run from the project folder (~/W):  python3 install_toolsmart.py
Gives the Answer Finder, Source Tracer and Topic Finder the same OpenAlex "meaning" search that Search Papers has,
and makes them use the optional AI ranking by themselves when you set it up (AI_BASE_URL, AI_API_KEY, AI_EMBED_MODEL in Render).
Real papers only; nothing is written by AI. Safe to run twice. A file that does not match is left alone with a warning."""
import json, os, sys

MOD = '"""toolsmart.py: the same OpenAlex "meaning" search (and the optional AI ranking) for the tools\n(Answer Finder, Source Tracer, Topic Finder). Lives next to engine.py.\n\nIt only finds and orders REAL papers. It never writes text. Everything is optional and fails safe: if anything goes wrong\nthe tools simply carry on with their normal searches.\n\nSettings (Render > Environment, all optional):\n  TOOLS_SMART              "1" (default) = on, "0" = off\n  TOOLS_SMART_DAILY_LIMIT  most meaning searches per day for the tools (default 60)\n  AI_BASE_URL, AI_API_KEY, AI_EMBED_MODEL ...  the optional AI ranking (smartrank.py). Nothing to change here:\n                           when those are set, the tools use it by themselves.\n"""\nimport os\nimport time\nfrom concurrent.futures import ThreadPoolExecutor\n\nimport requests\n\n_pool = ThreadPoolExecutor(max_workers=4)\n_day = {"day": None, "n": 0}\nVIA = "similar meaning (OpenAlex AI search)"\n\n\ndef _env(name, default=""):\n    return (os.environ.get(name, default) or "").strip()\n\n\ndef enabled():\n    return _env("TOOLS_SMART", "1") == "1"\n\n\ndef _limit():\n    try:\n        return int(_env("TOOLS_SMART_DAILY_LIMIT", "60"))\n    except ValueError:\n        return 60\n\n\ndef _allowed():\n    today = time.strftime("%Y-%m-%d")\n    if _day["day"] != today:\n        _day["day"], _day["n"] = today, 0\n    if _day["n"] >= _limit():\n        return False\n    _day["n"] += 1\n    return True\n\n\ndef _fetch(query, f):\n    import core                                       # late import: avoids circular imports at start-up\n    params = {"search.semantic": query[:2000], "per-page": 50}\n    flt = []\n    if f.get("year_from"):\n        flt.append("from_publication_date:%s-01-01" % f["year_from"])\n    if f.get("year_to"):\n        flt.append("to_publication_date:%s-12-31" % f["year_to"])\n    if f.get("oa_only"):\n        flt.append("is_oa:true")\n    if flt:\n        params["filter"] = ",".join(flt)\n    key = getattr(core, "OPENALEX_API_KEY", "")\n    if key:\n        params["api_key"] = key\n    resp = requests.get(core.OPENALEX_URL, params=params, timeout=12)\n    if not resp.ok:\n        return []\n    out = []\n    for w in resp.json().get("results", []):\n        p = core.format_paper(w)\n        p["via"] = VIA\n        p["smart"] = True\n        out.append(p)\n    return out\n\n\ndef start(query, f):\n    """Begin the meaning search in the background so it runs while the normal searches run. Returns a handle or None."""\n    try:\n        query = (query or "").strip()\n        if not query or not enabled():\n            return None\n        if "openalex" not in (f.get("sources") or ["openalex"]):\n            return None                               # the person switched OpenAlex off\n        if not _allowed():\n            return None\n        return _pool.submit(_fetch, query, f)\n    except Exception:\n        return None\n\n\ndef result(handle, timeout=14):\n    """The papers from start(), or [] if it was off, slow or failed."""\n    if handle is None:\n        return []\n    try:\n        return handle.result(timeout=timeout) or []\n    except Exception:\n        return []\n\n\n# ── optional AI ranking (uses smartrank.py when it is set up; otherwise does nothing) ──\ndef _sims(query, papers):\n    try:\n        import smartrank\n        if not smartrank.available():\n            return None\n        pool = [p for p in papers if p.get("title")][:smartrank.pool_size()]\n        s = smartrank.similarities(query, pool)\n        if not s or len(s) != len(pool):\n            return None\n        lo, hi = min(s), max(s)\n        span = (hi - lo) or 1.0\n        return pool, [(x - lo) / span for x in s]\n    except Exception:\n        return None\n\n\ndef ai_mark(papers, query):\n    """Give the closest papers an \'ai_bonus\' between 0 and 1. No-op when the AI is off."""\n    got = _sims(query, papers)\n    if got:\n        for p, n in zip(*got):\n            p["ai_bonus"] = round(n, 3)\n\n\ndef ai_ranks(papers, query, ranks, keyfn, weight=0.4):\n    """Add a bonus to a {paper key: 0..1} rank table. Returns the table (unchanged when the AI is off)."""\n    got = _sims(query, papers)\n    if got:\n        for p, n in zip(*got):\n            k = keyfn(p)\n            ranks[k] = min(1.0, ranks.get(k, 0.0) + weight * n)\n    return ranks\n\n\ndef ai_sort(papers, query, f):\n    """For the \'best match\' order only: put the papers the AI finds closest first."""\n    if (f or {}).get("sort") != "match":\n        return\n    ai_mark(papers, query)\n    if any(p.get("ai_bonus") for p in papers):\n        papers.sort(key=lambda p: p.get("ai_bonus") or 0.0, reverse=True)       # stable\n\n\ndef diag():\n    return {"tools_smart_on": enabled(), "tools_searches_today": _day["n"], "tools_daily_limit": _limit()}\n'
SPEC = json.loads('{"answer_tool.py": [["import topicfinder\\n", "import topicfinder\\nimport toolsmart\\n"], ["        with ThreadPoolExecutor(max_workers=len(queries)) as ex:                 # several wordings at once: reviews and overviews\\n            batches = list(ex.map(lambda qq: search_papers(qq, 1, pool_f, per_source=ANSWER_PER_SOURCE)[0], queries))\\n        papers = _merge_keep_abstract(batches)\\n", "        _sm = toolsmart.start(query, f)                                           # meaning search, runs at the same time\\n        with ThreadPoolExecutor(max_workers=len(queries)) as ex:                 # several wordings at once: reviews and overviews\\n            batches = list(ex.map(lambda qq: search_papers(qq, 1, pool_f, per_source=ANSWER_PER_SOURCE)[0], queries))\\n        batches = batches + [toolsmart.result(_sm)]\\n        papers = _merge_keep_abstract(batches)\\n        toolsmart.ai_mark(papers, query)                                          # optional AI ranking; does nothing when it is off\\n"], ["    return c[\\"score\\"] + 0.5 * c.get(\\"tboost\\", 0) + 1.2 * math.log10(1 + (c[\\"paper\\"].get(\\"citations\\") or 0))\\n", "    return (c[\\"score\\"] + 0.5 * c.get(\\"tboost\\", 0) + 1.2 * math.log10(1 + (c[\\"paper\\"].get(\\"citations\\") or 0))\\n            + 1.0 * (c[\\"paper\\"].get(\\"ai_bonus\\") or 0))\\n"]], "tracer_tool.py": [["import topicfinder\\n", "import topicfinder\\nimport toolsmart\\n"], ["    ex = ThreadPoolExecutor(max_workers=len(jobs))\\n    futs = [ex.submit(run, j) for j in jobs]\\n", "    _sm = toolsmart.start(quote, f)                        # meaning search, runs at the same time\\n    ex = ThreadPoolExecutor(max_workers=len(jobs))\\n    futs = [ex.submit(run, j) for j in jobs]\\n"], ["    rank, allraw = {}, []\\n", "    batches.append(toolsmart.result(_sm))\\n    rank, allraw = {}, []\\n"], ["    return papers, {k: min(1.0, v / 1.5) for k, v in rank.items()}\\n", "    ranks = {k: min(1.0, v / 1.5) for k, v in rank.items()}\\n    return papers, toolsmart.ai_ranks(papers, quote, ranks, _pkey)\\n"]], "topic_tool.py": [["import topicfinder\\n", "import topicfinder\\nimport toolsmart\\n"], ["        with ThreadPoolExecutor(max_workers=len(jobs)) as ex:\\n            first = list(ex.map(lambda j: search_papers(j[0], 1, dict(f, sort=j[1]), per_source=25)[0], jobs))\\n", "        _sm = toolsmart.start(full_query, f)                          # meaning search, runs at the same time\\n        with ThreadPoolExecutor(max_workers=len(jobs)) as ex:\\n            first = list(ex.map(lambda j: search_papers(j[0], 1, dict(f, sort=j[1]), per_source=25)[0], jobs))\\n        first = first + [toolsmart.result(_sm)]\\n"], ["        papers = apply_filters_and_sort(papers, f, full_query)\\n", "        papers = apply_filters_and_sort(papers, f, full_query)\\n        toolsmart.ai_sort(papers, full_query, f)                      # optional AI ranking; does nothing when it is off\\n"]]}')

def find(name):
    for c in (name, os.path.join("routes", name), os.path.join("templates", name)):
        if os.path.isfile(c):
            return c
def read(p): return open(p, encoding="utf-8").read()
def write(p, t): open(p + ".new", "w", encoding="utf-8", newline="").write(t); os.replace(p + ".new", p)
def done(t, old, new): return new in t or (new.endswith(old) and new[:-len(old)] in t)

eng = find("engine.py")
if not eng:
    print("engine.py not found. Run this from the project folder (~/W)."); sys.exit(1)
ok, warn = [], []
for name, pairs in SPEC.items():
    p = find(name)
    if not p:
        warn.append(name + ": not found, left alone"); continue
    t, n, bad = read(p), 0, []
    for old, new in pairs:
        if done(t, old, new): continue
        if t.count(old) == 1:
            t = t.replace(old, new, 1); n += 1
        else:
            bad.append(old[:70].replace("\n", " "))
    if bad:
        warn.append(name + ": left alone, did not match: " + " | ".join(bad)); continue
    if n:
        write(p, t); ok.append(p)
target = os.path.join(os.path.dirname(eng) or ".", "toolsmart.py")
if not os.path.isfile(target) or read(target) != MOD:
    write(target, MOD); ok.append(target)
if not os.path.isfile(os.path.join(os.path.dirname(eng) or ".", "smartrank.py")):
    warn.append("smartrank.py is not installed (install_ai.py). The meaning search works; the optional AI ranking stays off.")
print("Updated:", ", ".join(ok) or "nothing (already done?)")
for w in warn: print("  note:", w)
